signature.advancedArgs:
{
  "type": "object",
  "properties": {
    "updateType": {
      "type": "string",
      "enum": [
        "educationalAndProfessionalQualifications",
        "workExperienceDetails",
        "membershipDetails",
        "bankDetails",
        "creditCardDetails",
        "passportAndOtherArticles",
        "assigendNonCashBenefit",
        "assignLanguage"
      ],
      "description": "Specifies the entity based on the query. This is used to determine the update feature."
    },
    "educationalAndProfessionalQualifications": {
      "type": "object",
      "description": "Before proceeding with the update, if the user ask query qualificationd details first qualification type exist record or not the after update. no qualification type record no update.first check whether the user is invoking the 'next qualification' API. If so, execute the 'qualificationTypesandQualification' API to fetch the relevant data. The AI must not generate any random dates during this process. The fields 'qualificationEffectStartDate' and 'qualificationEffectEndDate' must be derived solely from qualification data and must not be taken from any reimbursement-related records. All dates should follow the 'dd/mm/yyyy' format.",
      "properties": {
        "employeeNumber": {
          "type": "string",
          "description": "Unique identifier for the employee."
        },
        "skipType": {
          "type": "string",
          "description": "If the user updates the qualification type or qualification, the 'next qualification type' tool must be executed before updating 'educationalAndProfessionalQualifications'—but only if the user explicitly requests changes to education or qualification details. Otherwise, skip the 'next qualification type' tool and directly execute 'updateEmployeeInformationDetails'. If skipped, return the keyword 'skip'."
        },
        "qualificationTypeId": {
          "type": "string",
          "description": "ID for the selected qualification type. This is obtained from the list displayed by the 'qualificationTypes' tool."
        },
        "qualificationEffectStartDate": {
          "type": "string",
          "description": "Start date for the qualification's effect. This must follow the 'dd/mm/yyyy' format (e.g., '01/04/2025'). The value should be retrieved from qualification data only, not from reimbursement-related data. Random dates must not be generated."
        },
        "qualificationEffectEndDate": {
          "type": "string",
          "description": "End date for the qualification's effect. This must follow the 'dd/mm/yyyy' format (e.g., '01/04/2025'). The value should be retrieved from qualification data only. Do not use reimbursement-related dates, and do not generate any random dates."
        },
        "qualificationId": {
          "type": "string",
          "description": "ID for the selected qualification. This value is derived from the user's selection after displaying data using the 'qualificationTypes' tool. If the user manually updates the qualification input, the corresponding value should be captured. Otherwise, use the most recently fetched value."
        },
        "institutionName": {
          "type": "string",
          "description": "Name of the school or institution where the qualification was obtained. This is a required field and must be asked explicitly."
        },
        "highestQualification": {
          "type": "string",
          "enum": [
            "on",
            "off"
          ],
          "description": "Indicates whether this is the highest qualification. The value should be derived after calling the 'qualificationTypes' API."
        },
        "qualificationStatus": {
          "type": "string",
          "enum": [
            "0",
            "1",
            "2"
          ],
          "description": "Status of the qualification (0 = Pass, 1 = First Class, 2 = Second Class). This is a required field and must be asked explicitly. If the user provides an updated value, it should be used."
        },
        "jobRelated": {
          "type": "string",
          "enum": [
            "0",
            "1"
          ],
          "description": "Indicates whether the qualification is job-related (0 = No, 1 = Yes). This value should be fetched from previously obtained API data."
        },
        "durationValue": {
          "type": "string",
          "description": "Numeric duration of the qualification (e.g., '3.00' or '5.00'). If the user provides a number, format it accordingly."
        },
        "durationType": {
          "type": "string",
          "enum": [
            "000001",
            "000002",
            "000003",
            "000004",
            "000005"
          ],
          "description": "Type of duration. Values represent: 000001 = Years, 000002 = Months, 000003 = Weeks, 000004 = Days, 000005 = Hours."
        },
        "yearOfPassing": {
          "type": "string",
          "description": "Year in which the qualification was completed (e.g., '2023'). This is a required field and must be asked explicitly. It should be derived using the 'qualificationTypes' API."
        },
        "comments": {
          "type": "string",
          "description": "Any additional comments related to the qualification."
        },
        "totalCost": {
          "type": "string",
          "description": "Total cost incurred for obtaining the qualification. This value is retrieved using the 'qualificationTypes' API."
        },
        "currencyForTotalCost": {
          "type": "string",
          "description": "Currency code for the total cost. This is selected from the currency list provided by the 'qualificationTypes' API."
        },
        "CostEffectDate": {
          "type": "string",
          "format": "date",
          "description": "Effective date of the total cost. Must be in 'dd/mm/yyyy' format (e.g., '12/06/2025')."
        },
        "reimbursedAmount": {
          "type": "string",
          "description": "Amount reimbursed by the company. Retrieved using the 'qualificationTypes' API."
        },
        "currencyForReimbursement": {
          "type": "string",
          "description": "Currency code for the reimbursed amount. This is selected from the currency list retrieved via the 'qualificationTypes' API."
        },
        "reimbursementEffectDate": {
          "type": "string",
          "format": "date",
          "description": "Effective date of the reimbursement. Must follow the 'dd/mm/yyyy' format (e.g., '12/06/2025')."
        }
      },
      "required": [
        "employeeNumber",
        "qualificationTypeId",
        "qualificationId",
        "institutionName",
        "qualificationStatus",
        "durationValue",
        "durationType",
        "CostEffectDate",
        "reimbursementEffectDate",
        "highestQualification",
        "jobRelated",
        "skipType",
        "qualificationEffectStartDate",
        "qualificationEffectEndDate"
      ]
    },
    "workExperienceDetails": {
      "type": "object",
      "description": "To populate this schema, first execute the 'workExpDetails' API to fetch all existing work experience data. If the user does not update a specific field, use the corresponding value from the 'workExpDetails' API. must should analize what is human update message or what is before api get data to analize the date range corresponding data types return.",
      "properties": {
        "employeeNumber": {
          "type": "string",
          "description": "Unique identifier for the employee."
        },
        "category": {
          "type": "string",
          "description": "before api get in this filed like 'Internal' or 'External' category type"
        },
        "companyname": {
          "type": "string",
          "description": "Company name entered by the user. If not provided, use the value from the 'workExpDetails' API.if the user update category type for external must should give the compan name and you ask user campany name will take name."
        },
        "isWorkRelated": {
          "type": "string",
          "enum": [
            "on"
          ],
          "description": "Indicates whether the experience is work-related. If not provided, use the value from the 'workExpDetails' API."
        },
        "startDate": {
          "type": "string",
          "format": "date",
          "description": "Start date of the employment. If not provided, use the value from the 'workExpDetails' API."
        },
        "startDateType": {
          "type": "string",
          "enum": [
            "updateStartDate"
          ],
          "description": "Analyze the user query, and if the updated message includes a date reference for a human message, return it under the 'updateStartDate' key. If there is no date mentioned in the human message update, do not return updateStartDate."
        },
        "endDate": {
          "type": "string",
          "format": "date",
          "description": "End date of the employment. If not provided, use the value from the 'workExpDetails' API."
        },
        "endDateType": {
          "type": "string",
          "enum": [
            "updateEndDate"
          ],
          "description": "Analyze the user query, and if the updated human message includes an end date, return it under the 'updateEndDate' key. If no end date is mentioned in the human message update, do not return updateEndDate."
        },
        "confirmationDate": {
          "type": "string",
          "format": "date",
          "description": "Confirmation date of the job. If not provided, use the value from the 'workExpDetails' API."
        },
        "contactPerson": {
          "type": "string",
          "description": "Name of the contact person at the organization. if the user update contract persion take new update value. If not provided, use the value from the 'workExpDetails' API. if the user update value will be takr else dont dynamic genarate the value. to get the related for 'workExpDetails' api"
        },
        "department": {
          "type": "string",
          "description": "Department and devision in this field where the user worked. If not provided, use the value from the 'workExpDetails' API. if the user update value will be takr else dont dynamic genarate the value. to get the related for 'workExpDetails' api"
        },
        "position": {
          "type": "string",
          "description": "Position held by the user. If not provided, use the value from the 'workExpDetails' API."
        },
        "reasonForLeaving": {
          "type": "string",
          "description": "Reason for leaving the job. If not provided, use the value from the 'workExpDetails' API."
        },
        "salaryAllowanceLeaving": {
          "type": "string",
          "description": "Salary at the Salary/ Allowance on Leaving. If not provided, use the value from the 'workExpDetails' API. if the user are get before must in this format for user give 5 to convert in this format 5.00 etc."
        },
        "benefitsofLiving": {
          "type": "string",
          "description": "Benefit of leaving. If not provided, use the value from the 'workExpDetails' API."
        },
        "companyAddress": {
          "type": "string",
          "description": "Address of the company. If not provided, use the value from the 'workExpDetails' API."
        },
        "contactNumber": {
          "type": "string",
          "description": "Contact phone number. If not provided, use the value from the 'workExpDetails' API."
        },
        "responsibilities": {
          "type": "string",
          "description": "Job responsibilities. If not provided, use the value from the 'workExpDetails' API."
        },
        "achievements": {
          "type": "string",
          "description": "Key achievements during tenure. If not provided, use the value from the 'workExpDetails' API."
        },
        "hasBenefits": {
          "type": "string",
          "enum": [
            "on"
          ],
          "description": "Indicates whether the user received any benefits. If not provided, use the value from the 'workExpDetails' API."
        }
      },
      "required": [
        "companyname",
        "isWorkRelated",
        "startDate",
        "endDate",
        "confirmationDate",
        "contactPerson",
        "department",
        "position",
        "reasonForLeaving",
        "lastDrawnSalary",
        "benefitsReceived",
        "companyAddress",
        "contactNumber",
        "responsibilities",
        "achievements",
        "hasBenefits"
      ]
    },
    "membershipDetails": {
      "title": "Update Membership Details",
      "description": "Before execute in the membership details api, first execute the 'getMembershipDetails' api, then next execute the 'updateMemberShipDetails' api, then finl execute in the api.Schema for validating data submitted to the 'updateMemberShipDetails' api. 'updateMemberShipDetails' api is used to update only the fields explicitly provided by the user. If any field is missing, the API will use corresponding existing values — do not generate or assume dynamic/default values. and some fields are hiden fields cant not update membership type and membership if the user update for check and return validation message return. Note : in the particular use cased no need execute the 'getEmployeeInformationDetails' api.",
      "type": "object",
      "properties": {
        "empEmpNumber": {
          "type": "string",
          "description": "Unique employee number. Example: '000001'."
        },
        "membershipNum": {
          "type": "string",
          "description": "Membership numbers if the user given update value will be take the update value if the the user not update to get the corresponding data value for 'updateMemberShipDetails' tool (e.g., 0, 1, 2)."
        },
        "subscriptionOwnership": {
          "type": "string",
