        },
        "membershipTitleId": {
          "type": "string",
          "description": "Selected membership title ID from dropdown. Example: '000001' if the user given update value will be take the update value if the the user not update to get the corresponding data for 'updateMemberShipDetails' tool."
        },
        "startDate": {
          "type": "string",
          "description": "Membership Commencement Date in DD/MM/YYYY format. Example: '22/12/2023'. if the user given update value will be take the update value if the the user not update to get the corresponding date for 'updateMemberShipDetails' tool"
        },
        "endDate": {
          "type": "string",
          "description": "Membership end or renewal date in DD/MM/YYYY format. Example: '22/12/2023'. if the user given update value will be take the update value if the the user not update to get the corresponding date for 'updateMemberShipDetails' tool"
        },
        "paidbyIndividualAmount": {
          "type": "string",
          "description": "Amount paid by the individual.if the user given update value will be take the update value if the the user not update to get the corresponding data value for 'updateMemberShipDetails' tool"
        },
        "individualCurrency": {
          "type": "string",
          "description": "Currency code for individual payment. Use the corresponding value for the selected currency. Example: '000001'. if the user given update value will be take the update value if the the user not update to get the corresponding data value for 'updateMemberShipDetails' tool"
        },
        "individualEffDate": {
          "type": "string",
          "description": "Effective date for individual payment in DD/MM/YYYY format. Example: '22/12/2023'. if the user given update value will be take the update value if the the user not update to get the corresponding date for 'updateMemberShipDetails' tool"
        },
        "paidbyCompanyAmount": {
          "type": "string",
          "description": "Amount paid by the company.if the user given update value will be take the update value if the the user not update to get the corresponding data value for 'updateMemberShipDetails' tool"
        },
        "companyCurrency": {
          "type": "string",
          "description": "Currency code for company payment. Use the corresponding value for the selected currency. Example: '000001'. if the user given update value will be take the update value if the the user not update to get the corresponding data value for 'updateMemberShipDetails' tool"
        },
        "companyEffDate": {
          "type": "string",
          "description": "Effective date for company payment in DD/MM/YYYY format. Example: '22/12/2023'. if the user given update value will be take the update value if the the user not update to get the corresponding data for 'updateMemberShipDetails' tool"
        }
      },
      "required": [
        "empEmpNumber",
        "membershipNum",
        "subscriptionOwnership",
        "membershipTitleId",
        "startDate",
        "endDate",
        "individualAmount",
        "individualCurrency",
        "individualEffDate",
        "companyAmount",
        "companyCurrency",
        "companyEffDate",
        "paidbyCompanyAmount",
        "paidbyIndividualAmount"
      ]
    },
    "bankDetails": {
      "type": "object",
      "description": "if the user update credit card details must be updateType value is 'bankDetails'.First, execute the 'specificBankEmployeeDetails' tool to retrieve the initial set of bank details for the employee. If the user does not provide an updated value for a particular field, retain the existing value from the 'specificBankEmployeeDetails' response. No dynamic or inferred data should be added to the schema—only explicitly provided or existing values should be used. If the user requests or refers to an order number (e.g., 1, 2, 3, etc.) that does not match any records, the system should still store the request as a reference but flag that the order number does not match the available records. Additionally, whenever the user intends to update any bank detail fields, they must be prompted to provide a valid order number to ensure accurate record identification and update.",
      "properties": {
        "accountType": {
          "type": "string",
          "description": "Account Type (e.g., 0 = Current, 1 = Savings, 2 = Third Party, 3 = Bonus, 4 = External). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "currency": {
          "type": "string",
          "description": "Currency Code (e.g., 000081 for Sri Lanka Rupee). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "accountName": {
          "type": "string",
          "description": "Name provided to the bank for the account.to get the account name for 'specificBankEmployeeDetails' tool."
        },
        "amountType": {
          "type": "string",
          "description": "Amount Type (0 = Fixed Amount, 1 = Percentage). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "order": {
          "type": "string",
          "description": "if the any update bank details must be ask the order number.Priority order for the bank account. This value must be explicitly provided by the user before calling this API. must should ask the user order number example 1,2,3 etc..."
        },
        "isActive": {
          "type": "string",
          "enum": [
            "on",
            "off"
          ],
          "description": "Whether the bank account is active ('on') or inactive ('off'). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "startDate": {
          "type": "string",
          "description": "Start date of the bank account (format: m/d/yyyy). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "endDate": {
          "type": "string",
          "description": "End date of the bank account (format: m/d/yyyy). Use the user's updated value if provided; otherwise, use the value from the 'specificBankEmployeeDetails' tool."
        },
        "comment": {
          "type": "string",
          "description": "Additional comments provided by the user."
        },
        "currentAmount": {
          "type": "string",
          "description": "Current amount value used for internal comparison. to get the current to use the ammount value from the 'specificBankEmployeeDetails' tool."
        },
        "updateAmount": {
          "type": "string",
          "description": "update amount type (typically mirrors 'update amount value', used internally). Use the user's updated value if provided"
        },
        "employeeNumber": {
          "type": "string",
          "description": "Unique identifier for the employee."
        },
        "accountNumber": {
          "type": "string",
          "description": "to get the account number for 'specificBankEmployeeDetails' api data"
        }
      },
      "required": [
        "accountType",
        "currency",
        "accountName",
        "amountType",
        "order",
        "isActive",
        "startDate",
        "endDate",
        "comment",
        "currentAmount",
        "updateAmount",
        "employeeNumber",
        "accountNumber"
      ]
    },
    "creditCardDetails": {
      "type": "object",
      "description": "if the user update credit card details must be updateType value is 'creditCardDetails'. if the user update the credit card update related query updateType name is 'creditCardDetails'. execute the dateFormat api using date format. First, execute the 'specificCreditCardDetails' tool to retrieve the initial data. If the user does not provide an updated value for any field, use the value from the 'specificCreditCardDetails' response. Do not include any dynamically generated or inferred data. all data schema get then execute finall execute in this tool 'updateEmployeeInformationDetails' tool.",
      "properties": {
        "creditCardNumber": {
          "type": "string",
          "description": "This field is read-only and should be retrieved from the 'specificCreditCardDetails' tool. Users cannot edit this value."
        },
        "creditCardType": {
          "type": "string",
          "description": "The credit card type selected by the user. Valid values: '1' for Master and '0' for Visa. If the user does not update this, use the value from the 'specificCreditCardDetails' tool."
        },
        "issuedDate": {
          "type": "string",
          "description": "execute the dateFormat api using date format.The issue date of the card in 'dd/mm/yyyy' format. If the user does not update this, use the value from the 'specificCreditCardDetails' tool."
        },
        "expiryDate": {
          "type": "string",
          "description": "execute the dateFormat api using date format.The expiry date of the card in 'dd/mm/yyyy' format. If the user does not update this, use the value from the 'specificCreditCardDetails' tool."
        },
        "employeeNumber": {
          "type": "string",
          "description": "Unique identifier of the employee."
        }
      },
      "required": [
        "employeeNumber",
        "creditCardNumber",
        "creditCardType",
        "issuedDate",
        "expiryDate"
      ]
    },
    "passportAndOtherArticles": {
      "type": "object",
      "title": "Passport and Other Article Details",
      "description": "Before executing this API, you must first run the 'specificPassportAndOtherArticlesDetails' tool to retrieve the necessary data. If any fields are missing in the user's input, fetch the corresponding values from that tool. After ensuring all required fields are populated, proceed to call the 'updateEmployeeInformationDetails' tool.",
      "properties": {
        "employeeNumber": {
          "type": "string",
          "description": "Unique identifier assigned to the employee. Example: '000001'."
        },
        "articleCategory": {
          "type": "string",
          "description": "Code corresponding to the selected article category (e.g., Visa, Passport, Driving License). The value should be taken based on the selected display name. Example values: '0', '1', etc."
        },
        "documentNumber": {
          "type": "string",
          "description": "Unique identifier or number of the document. If not updated by the user, fetch the existing value using the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "articleSubcategory": {
          "type": "string",
          "description": "Subcategory or detailed classification of the article (e.g., Barangay clearance type). If not provided by the user, retrieve the value using the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "countryOfOrigin": {
          "type": "string",
          "description": "Code of the country where the document was issued. The value should correspond to the selected country name. Example: '000176' for Pitcairn. If not provided, retrieve it using the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "numberOfEntries": {
          "type": "string",
          "description": "Indicates how many entries the document allows (commonly for visas). If not provided, get the value from the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "placeOfIssue": {
          "type": "string",
          "description": "The place or authority that issued the document. If not updated by the user, fetch the value using the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "issueDate": {
          "type": "string",
          "description": "execute the dateFormat api using date format.The issue date of the card in 'dd/mm/yyyy' format.. If not updated by the user, fetch it from the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "expiryDate": {
          "type": "string",
          "description": "execute the dateFormat api using date format.The issue date of the card in 'dd/mm/yyyy' format.. If not provided, retrieve it using the 'specificPassportAndOtherArticlesDetails' tool."
        },
        "comments": {
          "type": "string",
          "description": "Any additional remarks or information related to the document. If not provided by the user, fetch it from the 'specificPassportAndOtherArticlesDetails' tool."
        }
      },
      "required": [
        "employeeNumber",
        "articleCategory",
        "documentNumber",
        "articleSubcategory",
        "countryOfOrigin",
        "numberOfEntries",
        "placeOfIssue",
        "issueDate",
        "expiryDate",
        "comments"
      ]
    },
