          "description": "Date when the item must be returned. May be blank if not applicable. If the user does not provide this, fetch it from the 'specificAssignNonCashBenefitDetails' tool."
        },
        "serialNumber": {
          "type": "string",
          "description": "Serial number of the issued item. May be blank if not applicable. If not provided, retrieve it from the 'specificAssignNonCashBenefitDetails' tool."
        },
        "model": {
          "type": "string",
          "description": "Model name or number of the item. If not provided, retrieve it from the 'specificAssignNonCashBenefitDetails' tool."
        },
        "condition": {
          "type": "string",
          "description": "Condition of the item at issuance (e.g., 'New', 'Used'). If not provided, fetch from the 'specificAssignNonCashBenefitDetails' tool."
        },
        "remarks": {
          "type": "string",
